-- =============================================================================
-- AssetFlow Pro — Bootstrap Seed
-- File   : docker/postgres/init/02-seed.sql
-- Purpose: Inserts the minimum data required to log in on a fresh container.
--          Runs after 01-schema.sql. Fully idempotent (ON CONFLICT DO NOTHING).
--
-- PASSWORD STRATEGY
-- -----------------
-- The app uses bcrypt (cost factor 10) for all password storage and comparison.
-- This seed stores the admin password as a bcrypt hash generated by pgcrypto's
-- crypt() function (produces a $2a$ Blowfish hash compatible with bcryptjs.compare).
--
-- Default password: ChangeMe123!
--
-- OPERATOR CHECKLIST BEFORE GOING TO PRODUCTION
-- -----------------------------------------------
-- 1. Log in immediately after first boot and change the password via the UI.
-- 2. Alternatively, update this file with a different password string inside
--    the crypt() call, then rebuild the container.
-- 3. Change email and name to match your environment if desired.
-- 4. This file is safe to re-run (ON CONFLICT DO NOTHING); deleting it after
--    first boot prevents accidental re-seeding on container rebuild.
-- =============================================================================

INSERT INTO public.users (
  id,
  email,
  name,
  password,
  role,
  "roleLabel",
  department,
  position,
  avatar,
  phone,
  bio,
  status,
  company,
  tags,
  module_permissions,
  created_at,
  updated_at,
  created_by,
  updated_by
)
VALUES (
  'usr-admin-001',
  'admin@assetflow.local',
  'System Administrator',
  -- bcrypt hash of 'ChangeMe123!' (cost 10, pgcrypto Blowfish, compatible with bcryptjs).
  -- Change the password string inside crypt() to seed a different default password.
  crypt('ChangeMe123!', gen_salt('bf', 10)),
  'super_admin',
  'Super Admin',
  'Ban Giám Đốc',
  'Quản Trị Viên Hệ Thống',
  'SA',
  '0000000000',
  'Tài khoản quản trị khởi tạo tự động. Vui lòng đổi mật khẩu ngay sau lần đăng nhập đầu tiên.',
  'active',
  'FADO Group',
  '{}',
  '{}'::JSONB,
  NOW(),
  NOW(),
  'system',
  'system'
)
ON CONFLICT (email) DO NOTHING;

