-- Sample Departments (linked to first company)
-- Get the first company ID dynamically
INSERT INTO public.departments (id, company_id, name, code, description, manager_id, is_active, created_at, updated_at)
SELECT
  gen_random_uuid(),
  c.id,
  dept.name,
  dept.code,
  dept.description,
  'usr-admin-001'::TEXT,
  true,
  NOW(),
  NOW()
FROM companies c
CROSS JOIN (
  VALUES
    ('Phòng Hành Chính', 'ADM', 'Bộ phận hành chính công ty'),
    ('Phòng CNTT', 'IT', 'Bộ phận công nghệ thông tin'),
    ('Phòng Nhân Sự', 'HR', 'Bộ phận quản lý nhân sự'),
    ('Phòng Kinh Doanh', 'SALES', 'Bộ phận kinh doanh và marketing'),
    ('Phòng Tài Chính', 'FIN', 'Bộ phận quản lý tài chính')
) AS dept(name, code, description)
WHERE c.name = 'FADO Group'
ON CONFLICT DO NOTHING;

-- Sample Positions (linked to first company)
INSERT INTO public.positions (id, company_id, name, description, salary_min, salary_max, is_active, created_at, updated_at)
SELECT
  gen_random_uuid(),
  c.id,
  pos.name,
  pos.description,
  pos.salary_min,
  pos.salary_max,
  true,
  NOW(),
  NOW()
FROM companies c
CROSS JOIN (
  VALUES
    ('Giám Đốc Điều Hành', 'CEO - Quản lý toàn bộ công ty', 5000.00, 10000.00),
    ('Phó Giám Đốc', 'Hỗ trợ CEO quản lý hoạt động', 3000.00, 5000.00),
    ('Trưởng Phòng', 'Quản lý bộ phận', 2000.00, 3500.00),
    ('Phó Trưởng Phòng', 'Hỗ trợ Trưởng Phòng', 1500.00, 2500.00),
    ('Chuyên Viên', 'Thực hiện công việc chuyên môn', 1000.00, 1800.00),
    ('Nhân Viên', 'Thực hiện công việc hàng ngày', 600.00, 1200.00)
) AS pos(name, description, salary_min, salary_max)
WHERE c.name = 'FADO Group'
ON CONFLICT DO NOTHING;

-- Sample Job Titles (linked to first company)
INSERT INTO public.job_titles (id, company_id, title, description, is_active, created_at, updated_at)
SELECT
  gen_random_uuid(),
  c.id,
  jt.title,
  jt.description,
  true,
  NOW(),
  NOW()
FROM companies c
CROSS JOIN (
  VALUES
    ('Senior Developer', 'Lập trình viên cấp cao'),
    ('Frontend Developer', 'Lập trình viên giao diện'),
    ('Backend Developer', 'Lập trình viên server'),
    ('QA Engineer', 'Kỹ sư kiểm thử'),
    ('DevOps Engineer', 'Kỹ sư triển khai và vận hành'),
    ('Business Analyst', 'Phân tích yêu cầu kinh doanh'),
    ('Product Manager', 'Quản lý sản phẩm'),
    ('Scrum Master', 'Quản lý dự án Agile')
) AS jt(title, description)
WHERE c.name = 'FADO Group'
ON CONFLICT DO NOTHING;

